function mat(color, opacity = 1, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: opacity >= 1,
    ...opts
  });
}

function lineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: false
  });
}

function roundedRectShape(w, h, r) {
  const x = -w / 2, y = -h / 2;
  const s = new THREE.Shape();
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

function addRoundedRect(cx, cy, w, h, r, material, zz = 0) {
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(roundedRectShape(w, h, r)), material);
  mesh.position.set(cx, cy, zz);
  root.add(mesh);
  return mesh;
}

function addEllipse(cx, cy, rx, ry, material, zz = 0, segments = 96) {
  const geom = new THREE.CircleGeometry(1, segments);
  geom.scale(rx, ry, 1);
  const mesh = new THREE.Mesh(geom, material);
  mesh.position.set(cx, cy, zz);
  root.add(mesh);
  return mesh;
}

function ellipseLine(cx, cy, rx, ry, color = 0x9fb2bb, opacity = 0.55, zz = 0.1) {
  const curve = new THREE.EllipseCurve(cx, cy, rx, ry, 0, Math.PI * 2, false, 0);
  const pts = curve.getPoints(120).map(p => new THREE.Vector3(p.x, p.y, zz));
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat(color, opacity));
  root.add(line);
  return line;
}

function tubeFromPoints(points, radius, color, opacity = 1, zzOffset = 0, tubularSegments = 72) {
  const pts = points.map(p => new THREE.Vector3(p[0], p[1], (p[2] ?? 0) + zzOffset));
  const curve = new THREE.CatmullRomCurve3(pts, false, 'centripetal');
  const mesh = new THREE.Mesh(
    new THREE.TubeGeometry(curve, tubularSegments, radius, 10, false),
    mat(color, opacity)
  );
  root.add(mesh);
  return { mesh, curve };
}

function tubeLine(a, b, radius, color, opacity = 1, zzOffset = 0) {
  return tubeFromPoints([[a[0], a[1], a[2] ?? 0], [b[0], b[1], b[2] ?? 0]], radius, color, opacity, zzOffset, 2).mesh;
}

function arrowHead(x, y, angle, size = 0.28, color = 0x000000, zz = z.front) {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.lineTo(-size, -size * 0.42);
  shape.lineTo(-size * 0.78, 0);
  shape.lineTo(-size, size * 0.42);
  shape.lineTo(0, 0);
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape), mat(color, 1));
