  mesh.rotation.z = angle;
  root.add(mesh);
  return mesh;
}

function makeArrowGroup(x1, y1, x2, y2, color = 0x000000, radius = 0.025) {
  const group = new THREE.Group();
  root.add(group);
  const dx = x2 - x1, dy = y2 - y1;
  const len = Math.hypot(dx, dy);
  const ux = dx / len, uy = dy / len;
  const shaftPts = [
    new THREE.Vector3(x1, y1, z.front),
    new THREE.Vector3(x2 - ux * 0.24, y2 - uy * 0.24, z.front)
  ];
  const curve = new THREE.CatmullRomCurve3(shaftPts);
  const shaft = new THREE.Mesh(new THREE.TubeGeometry(curve, 2, radius, 8), mat(color, 1));
  group.add(shaft);
  const headShape = new THREE.Shape();
  const size = 0.32;
  headShape.moveTo(0, 0);
  headShape.lineTo(-size, -size * 0.43);
  headShape.lineTo(-size * 0.78, 0);
  headShape.lineTo(-size, size * 0.43);
  headShape.lineTo(0, 0);
  const head = new THREE.Mesh(new THREE.ShapeGeometry(headShape), mat(color, 1));
  head.position.set(x2, y2, z.front);
  head.rotation.z = Math.atan2(dy, dx);
  group.add(head);
  return group;
}

function makeCurvedArrow(start, mid, end, reverse = false) {
  const group = new THREE.Group();
  root.add(group);
  const s = reverse ? end : start;
  const e = reverse ? start : end;
  const curve = new THREE.QuadraticBezierCurve3(
    new THREE.Vector3(s[0], s[1], z.front),
    new THREE.Vector3(mid[0], mid[1], z.front),
    new THREE.Vector3(e[0], e[1], z.front)
  );
  const shaft = new THREE.Mesh(new THREE.TubeGeometry(curve, 36, 0.018, 8), mat(0x000000, 1));
  group.add(shaft);
  const tangent = curve.getTangent(1);
  const headShape = new THREE.Shape();
  const size = 0.23;
  headShape.moveTo(0, 0);
  headShape.lineTo(-size, -size * 0.42);
  headShape.lineTo(-size * 0.72, 0);
  headShape.lineTo(-size, size * 0.42);
  headShape.lineTo(0, 0);
  const head = new THREE.Mesh(new THREE.ShapeGeometry(headShape), mat(0x000000, 1));
  head.position.copy(curve.getPoint(1));
  head.rotation.z = Math.atan2(tangent.y, tangent.x);
  group.add(head);
  return group;
}

