  cellDirection: 'Cu cathode, SHE anode'
};

function fmtConc(c) {
  if (Math.abs(c - 1) < 1e-9) return '1';
  if (c < 0.1) return c.toFixed(2);
  if (c < 1) return c.toFixed(2).replace(/0$/, '');
  if (c < 10) return c.toFixed(2).replace(/\.?0+$/, '');
  return c.toFixed(0);
}

function cellPotential() {
  const base = 0.337 + (0.05916 / 2) * Math.log10(state.cuIonConcentration);
  return state.cellDirection === 'Cu cathode, SHE anode' ? base : -base;
}

function signedVolt(v) {
  return `${v >= 0 ? '+' : '−'}${Math.abs(v).toFixed(3)} V`;
}

function updateFigure() {
  const c = Math.max(0.01, Number(state.cuIonConcentration) || 1);
  state.cuIonConcentration = c;
  concSlider.value = String(c);
  concValue.textContent = `${fmtConc(c)} M`;
  labelEntries.cuBottom.div.innerHTML = `${fmtConc(c)} <i>M</i> Cu<sup>2+</sup>`;
  labelEntries.voltage.div.innerHTML = signedVolt(cellPotential());

  const t = (Math.log10(c) + 2) / 3;
  rightBeaker.liquid.material.opacity = THREE.MathUtils.clamp(0.46 + 0.30 * t, 0.42, 0.80);

  const normal = state.cellDirection === 'Cu cathode, SHE anode';
  directionSelect.value = state.cellDirection;
  electronArrowsNormal.visible = normal;
  electronArrowsReverse.visible = !normal;
  leftReactionNormal.visible = normal;
  leftReactionReverse.visible = !normal;
  rightReactionNormal.visible = normal;
  rightReactionReverse.visible = !normal;

  if (normal) {
    labelEntries.anode.div.innerHTML = 'Anode −';
    labelEntries.anode.pos.set(-4.22, -1.35, z.front);
    labelEntries.cathode.div.innerHTML = 'Cathode +';
    labelEntries.cathode.pos.set(4.05, -2.92, z.front);
    labelEntries.eFlow.div.innerHTML = 'e<sup>−</sup> flow';
  } else {
    labelEntries.anode.div.innerHTML = 'Cathode +';
    labelEntries.anode.pos.set(-4.22, -1.35, z.front);
    labelEntries.cathode.div.innerHTML = 'Anode −';
    labelEntries.cathode.pos.set(4.05, -2.92, z.front);
    labelEntries.eFlow.div.innerHTML = 'e<sup>−</sup> flow';
  }
}

