const demoSteps = [
  {
    title: 'Standard Cu/SHE galvanic cell',
    narration: 'With [Cu²⁺] = 1 M, H₂ at 1 atm, and H⁺ at 1 M, the voltmeter reads the standard cell potential, +0.337 V. Electrons flow from the standard hydrogen electrode to the copper electrode.',
    state: { cuIonConcentration: 1, cellDirection: 'Cu cathode, SHE anode' }
  },
  {
    title: 'Lower copper ion concentration',
    narration: 'Reducing [Cu²⁺] makes copper reduction less favorable, so the Nernst equation lowers the voltage below +0.337 V.',
    state: { cuIonConcentration: 0.1, cellDirection: 'Cu cathode, SHE anode' }
  },
  {
    title: 'Higher copper ion concentration',
    narration: 'Increasing [Cu²⁺] makes copper reduction more favorable, raising the measured potential above the standard value.',
    state: { cuIonConcentration: 10, cellDirection: 'Cu cathode, SHE anode' }
  },
  {
    title: 'Reverse the cell',
    narration: 'Swapping anode and cathode reverses the electron-flow arrows and changes the voltmeter reading to the opposite sign for the same chemical conditions.',
    state: { cuIonConcentration: 1, cellDirection: 'Cu anode, SHE cathode' }
  }
];

let currentStep = 0;
let tweenToken = 0;

function goToStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  const step = demoSteps[currentStep];
  stepTitle.textContent = step.title;
  stepNarration.textContent = step.narration;

  const startConc = state.cuIonConcentration;
  const endConc = step.state.cuIonConcentration;
  state.cellDirection = step.state.cellDirection;
  directionSelect.value = state.cellDirection;
  const token = ++tweenToken;
  const start = performance.now();
  const duration = 650;

  function ease(u) {
    return u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
  }

  function tick(now) {
    if (token !== tweenToken) return;
    const u = Math.min(1, (now - start) / duration);
    const logA = Math.log10(startConc);
    const logB = Math.log10(endConc);
    state.cuIonConcentration = Math.pow(10, logA + (logB - logA) * ease(u));
    updateFigure();
    if (u < 1) requestAnimationFrame(tick);
    else {
      state.cuIonConcentration = endConc;
      updateFigure();
    }
  }
  requestAnimationFrame(tick);
}

document.getElementById('stepPrev').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(currentStep + 1));
window.goToStep = goToStep;

function animateParticles(now) {
  requestAnimationFrame(animateParticles);
  const enabled = flowBox.checked;
  const normal = state.cellDirection === 'Cu cathode, SHE anode';
  const time = now * 0.00018;

  for (const p of electronParticles) {
    p.visible = enabled;
    if (!enabled) continue;
    let t = (p.userData.base + time) % 1;
    if (!normal) t = 1 - t;
    p.position.copy(wireParticleCurve.getPoint(t));
  }

  for (const p of ionParticles) {
    p.visible = enabled;
    if (!enabled) continue;
    let t = (p.userData.base + now * 0.00010) % 1;
    const isCation = p.userData.kind === 'cation';
    if (normal) {
      if (!isCation) t = 1 - t;
    } else {
      if (isCation) t = 1 - t;
    }
    p.position.copy(saltBridge.curve.getPoint(t));
    p.position.z = z.particles;
  }

  for (let i = 0; i < bubbleMeshes.length; i++) {
    const b = bubbleMeshes[i];
    if (!enabled) {
      b.visible = true;
      continue;
    }
    const baseY = bubblePositions[i][1];
    const phase = (now * 0.00022 + i * 0.137) % 1;
    b.position.y = baseY + phase * 0.55;
    if (b.position.y > -1.25) b.position.y -= 1.35;
  }
}
requestAnimationFrame(animateParticles);

updateFigure();
